package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen5Test {

    @Test
    public void testAbbreviate_NullString() {
        assertNull(WordUtils.abbreviate(null, 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_EmptyString() {
        assertEquals("", WordUtils.abbreviate("", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_UpperIsNegativeOne() {
        // upper = -1 sets upper to str.length()
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, -1, "..."));
    }

    @Test
    public void testAbbreviate_UpperGreaterThanLength() {
        // upper > length sets upper to str.length()
        assertEquals("Hello", WordUtils.abbreviate("Hello", 0, 10, "..."));
    }

    @Test
    public void testAbbreviate_UpperLessThanLower() {
        // upper < lower sets upper to lower
        // str="Hello", lower=4, upper=2 -> upper becomes 4. 
        // No space in "Hello" -> substring(0, 4) -> "Hell" + "..."
        assertEquals("Hell...", WordUtils.abbreviate("Hello", 4, 2, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInStringAndNoAbbreviation() {
        // upper == str.length(), no space found
        assertEquals("Hello", WordUtils.abbreviate("Hello", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInStringWithAbbreviation() {
        // upper < str.length(), no space found
        assertEquals("He...", WordUtils.abbreviate("Hello", 0, 2, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInStringWithNullAppend() {
        // appendToEnd is null, should use defaultString (empty)
        assertEquals("He", WordUtils.abbreviate("Hello", 0, 2, null));
    }

    @Test
    public void testAbbreviate_SpaceFoundAfterUpper() {
        // index of space is 6, upper is 3. index > upper.
        // result = str.substring(0, 3) + "..."
        assertEquals("Hel...", WordUtils.abbreviate("Hello World", 0, 3, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFoundBeforeUpper() {
        // index of space is 5, upper is 10. index < upper.
        // result = str.substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 10, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFoundAtLowerBoundary() {
        // Testing the 'else' block where index <= upper
        // "Hello World", lower=5, upper=10. Index of space is 5.
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 5, 10, "..."));
    }

    @Test
    public void testAbbreviate_UpperExactlyAtSpace() {
        // index is 5, upper is 5. index <= upper is true.
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 5, "..."));
    }
}
